    "topic": "宅建業法: 媒介契約（期間を問う）",
    "q": "専任媒介契約を締結した業者は、依頼者に対し、業務の処理状況を2週間に1回以上報告しなければならない。",
    "a": true,
    "why": "宅建業法34条の2第9項の定めによる。",
    "note": "",
    "sourceUrl": "https://laws.e-gov.go.jp/law/327AC1000000176#Mp-At_34_2"
