    "q": "登録の移転に伴って宅建士証の交付を受ける場合も、申請前6か月以内に行われる知事指定の講習を受講しなければならない。",
    "a": false,
    "why": "22条の2第2項ただし書により、移転に伴う宅建士証（同条5項）の交付では講習は不要。",
