    "q": "宅建士証が効力を失ったときは、速やかに宅建士証を自分の住所地を管轄する都道府県知事に返納しなければならない。",
    "a": false,
    "why": "返納先は住所地の知事ではなく、宅建士証の交付を受けた都道府県知事である（宅建業法22条の2第6項）。",
