    "topic": "宅建業法: 宅建士（試験・登録・取引士証）（比較を問う）",
    "q": "宅建士が事務禁止処分を受けたときは、宅建士証を交付を受けた都道府県知事に返納しなければならない。",
    "a": false,
    "why": "事務禁止処分のときは「返納」ではなく「提出」であり、禁止期間満了後に請求すれば返還される（宅建業法22条の2第7項・8項）。返納は登録消除・効力喪失のとき（同条6項）。",
    "note": "",
    "sourceUrl": "https://laws.e-gov.go.jp/law/327AC1000000176#Mp-At_22_2"
