    "t": "",
    "topic": "宅建業法: 広告（例外を問う）",
    "q": "同じ物件を数回に分けて広告する場合は、最初の広告で取引態様の別を明示すれば、2回目以降の広告では省略できる。",
    "a": false,
    "why": "宅建業法34条1項は広告をするときに明示を求め、省略を認める定めはない。各回の広告で明示が必要である。",
