    "q": "工事完了前の建物について、建築確認を受ける前は、貸借の媒介に関する広告もすることができない。",
    "a": true,
    "why": "宅建業法33条は、許可等の処分の後でなければ「売買その他の業務に関する広告」をしてはならないと定め、貸借の代理・媒介の広告も含まれる。",
