    "q": "工事完了前の建物でも、貸借の代理・媒介に関する広告であれば、建築確認を受ける前にすることができる。",
    "a": false,
    "why": "広告開始時期の制限（宅建業法33条）は「売買その他の業務に関する広告」が対象で、貸借も除外されていない。",
