    "t": "",
    "topic": "宅建業法: 広告（範囲を問う）",
    "q": "誇大広告等の禁止でいう「利用の制限」は、建築基準法などの公法上の制限に限られ、借地権の有無などの私法上の制限は含まれない。",
    "a": false,
    "why": "国交省「解釈・運用の考え方」第32条関係2(4)は、私法上の制限（借地権等の有無及び内容）も利用の制限に含める。",
