    "q": "誇大広告等の禁止に違反した者は、6月以下の拘禁刑若しくは100万円以下の罰金に処され、又はこれらが併科される。",
    "a": true,
    "why": "宅建業法81条1号（32条違反）。刑法改正（2025年6月1日施行）により、従来の「懲役」は「拘禁刑」となった。",
