    "topic": "宅建業法: 業務上の規制（47条・48条など）（範囲を問う）",
    "q": "契約締結の勧誘に先立って業者の商号又は名称と勧誘目的を告げれば、勧誘を行う者の氏名は告げなくてもよい。",
