    "q": "人の生命又は身体を害する不法行為による損害賠償請求権は、被害者又はその法定代理人が損害及び加害者を知った時から5年間行使しないときは、時効によって消滅する。",
    "a": true,
    "why": "民法724条の2が724条1号の「3年間」を「5年間」に読み替える。",
