    "video": "ru-dbc567ad",
    "t": "",
    "topic": "権利関係: 不法行為（数字を問う）",
    "q": "人の生命又は身体を害する不法行為による損害賠償請求権は、被害者が損害及び加害者を知った時から3年間行使しないときは、時効によって消滅する。",
    "a": false,
    "why": "民法724条の2により、生命・身体侵害の場合は知った時から5年間となる。",
