    "topic": "権利関係: 代理（例外を問う）",
    "q": "双方代理は、本人に損害が生じない内容であれば、本人の許諾がなくても有効な代理行為となる。",
    "a": false,
    "why": "民法108条1項の例外は「債務の履行」と「本人があらかじめ許諾した行為」だけで、損害の有無は問わない。許諾のない双方代理は無権代理行為とみなされる。",
