    "q": "本人の許諾なくされた双方代理は無効であり、本人が後から追認しても有効にはならない。",
    "a": false,
    "why": "民法108条1項により無権代理行為と「みなす」ので、本人は民法113条・116条により追認でき、追認すれば効力を生ずる。",
