    "topic": "権利関係: 保証・連帯債務・連帯債権（例外を問う）",
    "q": "債権者と他の連帯債務者の一人が別段の意思を表示していたときは、連帯債務者の一人に生じた事由の当該他の連帯債務者に対する効力は、その意思に従う。",
