    "q": "建物賃貸借が更新拒絶の通知がないために法定更新されたときは、従前の契約と同一の条件で更新されるが、期間は定めがないものとなる。",
    "a": true,
    "why": "借地借家法26条1項。",
    "note": "",
    "sourceUrl": "https://laws.e-gov.go.jp/law/403AC0000000090#Mp-At_26"
