    "t": "",
    "topic": "権利関係: 区分所有法（主体を問う）",
    "q": "規約で定めれば、区分所有者でも管理者でもない第三者を共用部分の所有者と定めることができる。",
    "a": false,
    "why": "区分所有法11条2項ただし書により、27条1項の管理者の場合を除き、区分所有者以外の者を共用部分の所有者と定めることはできない。",
