    "topic": "権利関係: 売買・契約不適合（主体を問う）",
    "q": "売買を媒介した宅地建物取引業者は、売主と連帯して、買主に対し目的物の修補をする担保責任を負う。",
    "a": false,
    "why": "追完請求の相手方は売主である（民法562条1項）。媒介業者が売主と連帯して担保責任を負う規定はない。",
