    "q": "自働債権が弁済期にあれば、受働債権の弁済期が到来していなくても、期限の利益を放棄して相殺することができる。",
    "a": true,
    "why": "相殺には双方の債務が弁済期にあることが必要（民法505条1項）だが、受働債権の債務者は期限の利益を放棄できる（同法136条2項）。",
