    "t": "",
    "topic": "権利関係: 意思表示（規則を問う）",
    "q": "詐欺による意思表示の取消しは、善意でかつ過失がない第三者に対抗することができない。",
    "a": true,
    "why": "民法96条3項。",
    "note": "",
    "sourceUrl": "https://laws.e-gov.go.jp/law/129AC0000000089#Mp-At_96"
