    "video": "ru-f8d1ee7e",
    "t": "",
    "topic": "権利関係: 意思表示（範囲を問う）",
    "q": "詐欺による意思表示の取消しは、善意の第三者であれば、過失があっても対抗することができない。",
    "a": false,
    "why": "保護されるのは「善意でかつ過失がない」第三者に限られる（民法96条3項）。",
