    "video": "ru-bf86dddf",
    "t": "",
    "topic": "法令上の制限: 農地法（規則を問う）",
    "q": "農地法上の農地に当たるかどうかは、登記簿上の地目ではなく、土地の現況によって判断する。",
    "a": true,
    "why": "農地法2条1項は農地を「耕作の目的に供される土地」とし、農林水産省の処理基準（第1(2)）は登記簿の地目で判断してはならないとする。",
    "note": "",
    "sourceUrl": "https://www.maff.go.jp/j/nousin/noukei/nouten/pdf/kizyun.pdf"
