    "video": "ru-bf86dddf",
    "t": "",
    "topic": "法令上の制限: 農地法（規則を問う）",
    "q": "登記簿上の地目が山林であれば、現に耕作されている土地であっても、農地法上の農地には当たらない。",
    "a": false,
    "why": "農地法2条1項と処理基準（第1(2)）により、現況で判断する。",
